import{_ as n,o as a,c as e,a5 as t}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"69. Error Handling and Return Codes","description":"The Little Book of C — 69. Error Handling and Return Codes","frontmatter":{"title":"69. Error Handling and Return Codes","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Working Close to the System"],"description":"The Little Book of C — 69. Error Handling and Return Codes","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":69,"sidebarWeight":69,"lang":"en-US","alternateEn":"/posts/c教程/en-US/07-Working Close to the System/069-Error Handling and Return Codes","alternateZh":"/posts/c教程/zh-CN/07-贴近系统/069-Error Handling and Return Codes"},"headers":[],"relativePath":"posts/c教程/en-US/07-Working Close to the System/069-Error Handling and Return Codes.md","filePath":"posts/c教程/en-US/07-Working Close to the System/069-Error Handling and Return Codes.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/en-US/07-Working Close to the System/069-Error Handling and Return Codes.md"};function i(l,s,o,r,d,c){return a(),e("div",null,[...s[0]||(s[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/07-贴近系统/069-Error Handling and Return Codes)</p><p>Every C program, from the tiniest script to the Linux kernel itself, relies on error codes and return values to communicate success or failure. Unlike higher-level languages, C gives you no exceptions, only clear, explicit status codes and<code>errno</code>.</p><p>Mastering these patterns will make your programs robust, predictable, and professional.</p><h4 id="step-1-exit-codes-and-main" tabindex="-1">Step 1. Exit Codes and main() <a class="header-anchor" href="#step-1-exit-codes-and-main" aria-label="Permalink to &quot;Step 1. Exit Codes and main()&quot;">​</a></h4><p>Every process returns an integer exit code to the operating system. Conventionally:</p><ul><li><code>0</code>→ success</li><li>nonzero → failure or specific error</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Everything OK!\\n&quot;);</span></span>
<span class="line"><span>    return 0; // exit success</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Check it in your shell:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./program</span></span>
<span class="line"><span>echo $?</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Everything OK!</span></span>
<span class="line"><span>0</span></span></code></pre></div><p>If you return a nonzero value:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>return 1;</span></span></code></pre></div><p>then<code>$?</code> will be<code>1</code>, meaning failure.</p><h4 id="step-2-using-exit-success-and-exit-failure" tabindex="-1">Step 2. Using EXIT_SUCCESS and EXIT_FAILURE <a class="header-anchor" href="#step-2-using-exit-success-and-exit-failure" aria-label="Permalink to &quot;Step 2. Using EXIT_SUCCESS and EXIT_FAILURE&quot;">​</a></h4><p>Instead of hardcoded numbers, use standard macros from<code>&lt;stdlib.h&gt;</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Failed to open file.\\n&quot;);</span></span>
<span class="line"><span>    return EXIT_FAILURE;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>These improve portability and readability.</p><h4 id="step-3-the-global-errno" tabindex="-1">Step 3. The Global errno <a class="header-anchor" href="#step-3-the-global-errno" aria-label="Permalink to &quot;Step 3. The Global errno&quot;">​</a></h4><p>When a library or system call fails, it usually sets a global variable named<code>errno</code>. It’s declared in<code>&lt;errno.h&gt;</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>#include &lt;fcntl.h&gt;</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fd = open(&quot;nonexistent.txt&quot;, O_RDONLY);</span></span>
<span class="line"><span>    if (fd == -1) {</span></span>
<span class="line"><span>        printf(&quot;Error opening file: %s\\n&quot;, strerror(errno));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error opening file: No such file or directory</span></span></code></pre></div><p><code>errno</code> stores an integer code, but<code>strerror()</code> converts it into a readable message.</p><h4 id="step-4-common-errno-values" tabindex="-1">Step 4. Common errno Values <a class="header-anchor" href="#step-4-common-errno-values" aria-label="Permalink to &quot;Step 4. Common errno Values&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Code</th><th>Macro</th><th>Meaning</th></tr></thead><tbody><tr><td>2</td><td><code>ENOENT</code></td><td>No such file or directory</td></tr><tr><td>13</td><td><code>EACCES</code></td><td>Permission denied</td></tr><tr><td>12</td><td><code>ENOMEM</code></td><td>Out of memory</td></tr><tr><td>22</td><td><code>EINVAL</code></td><td>Invalid argument</td></tr><tr><td>9</td><td><code>EBADF</code></td><td>Bad file descriptor</td></tr><tr><td>11</td><td><code>EAGAIN</code></td><td>Resource temporarily unavailable</td></tr></tbody></table><p>You can check them directly:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (errno == EACCES) { ... }</span></span></code></pre></div><h4 id="step-5-the-perror-function" tabindex="-1">Step 5. The perror() Function <a class="header-anchor" href="#step-5-the-perror-function" aria-label="Permalink to &quot;Step 5. The perror() Function&quot;">​</a></h4><p>A simpler way to print error messages is<code>perror()</code>, it automatically uses the current<code>errno</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;fcntl.h&gt;</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fd = open(&quot;nothing.txt&quot;, O_RDONLY);</span></span>
<span class="line"><span>    if (fd == -1) {</span></span>
<span class="line"><span>        perror(&quot;open&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>open: No such file or directory</span></span></code></pre></div><h4 id="step-6-returning-meaningful-codes" tabindex="-1">Step 6. Returning Meaningful Codes <a class="header-anchor" href="#step-6-returning-meaningful-codes" aria-label="Permalink to &quot;Step 6. Returning Meaningful Codes&quot;">​</a></h4><p>Good C programs translate internal errors into meaningful exit codes.</p><p>Example: file copy program</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>int main(int argc, char *argv[]) {</span></span>
<span class="line"><span>    if (argc != 3) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Usage: %s src dest\\n&quot;, argv[0]);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    FILE *src = fopen(argv[1], &quot;r&quot;);</span></span>
<span class="line"><span>    if (!src) {</span></span>
<span class="line"><span>        perror(&quot;fopen src&quot;);</span></span>
<span class="line"><span>        return 2;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    FILE *dst = fopen(argv[2], &quot;w&quot;);</span></span>
<span class="line"><span>    if (!dst) {</span></span>
<span class="line"><span>        perror(&quot;fopen dst&quot;);</span></span>
<span class="line"><span>        fclose(src);</span></span>
<span class="line"><span>        return 3;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    fclose(src);</span></span>
<span class="line"><span>    fclose(dst);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Now each exit code represents a specific type of failure.</p><h4 id="step-7-resetting-and-checking-errno" tabindex="-1">Step 7. Resetting and Checking errno <a class="header-anchor" href="#step-7-resetting-and-checking-errno" aria-label="Permalink to &quot;Step 7. Resetting and Checking errno&quot;">​</a></h4><p>Some system calls set<code>errno</code> only when they fail. So always reset it before use if you plan to inspect it later:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>errno = 0;</span></span>
<span class="line"><span>if (some_syscall() == -1) {</span></span>
<span class="line"><span>    perror(&quot;syscall failed&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="step-8-custom-error-handling-helpers" tabindex="-1">Step 8. Custom Error Handling Helpers <a class="header-anchor" href="#step-8-custom-error-handling-helpers" aria-label="Permalink to &quot;Step 8. Custom Error Handling Helpers&quot;">​</a></h4><p>You can create your own function to simplify error handling.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>void die(const char *msg) {</span></span>
<span class="line"><span>    perror(msg);</span></span>
<span class="line"><span>    exit(EXIT_FAILURE);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *f = fopen(&quot;no.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    if (!f) die(&quot;fopen&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fopen: No such file or directory</span></span></code></pre></div><p>This pattern appears throughout Unix utilities.</p><h4 id="step-9-handling-partial-failures" tabindex="-1">Step 9. Handling Partial Failures <a class="header-anchor" href="#step-9-handling-partial-failures" aria-label="Permalink to &quot;Step 9. Handling Partial Failures&quot;">​</a></h4><p>Not all errors should abort your program. Sometimes you should log, retry, or ignore.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FILE *f = fopen(&quot;optional.conf&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>if (!f) {</span></span>
<span class="line"><span>    fprintf(stderr, &quot;Warning: config file missing, using defaults.\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This kind of graceful degradation is good design.</p><h4 id="step-10-tiny-code-safe-file-reader" tabindex="-1">Step 10. Tiny Code: Safe File Reader <a class="header-anchor" href="#step-10-tiny-code-safe-file-reader" aria-label="Permalink to &quot;Step 10. Tiny Code: Safe File Reader&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *f = fopen(&quot;data.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    if (!f) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Error: %s\\n&quot;, strerror(errno));</span></span>
<span class="line"><span>        return EXIT_FAILURE;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    char buf[64];</span></span>
<span class="line"><span>    while (fgets(buf, sizeof(buf), f))</span></span>
<span class="line"><span>        printf(&quot;%s&quot;, buf);</span></span>
<span class="line"><span>    fclose(f);</span></span>
<span class="line"><span>    return EXIT_SUCCESS;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output (if missing file):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error: No such file or directory</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Error handling separates toy programs from real software:</p><ul><li>Every syscall can fail, be prepared.</li><li>Always check return values.</li><li>Always report why it failed.</li></ul><p>By convention:</p><ul><li>Return<code>0</code> on success.</li><li>Return nonzero for recoverable or fatal errors.</li><li>Print messages to<code>stderr</code>, not<code>stdout</code>.</li></ul><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Open a nonexistent file and print the full<code>errno</code> value.</li><li>Build a small utility that returns specific codes for specific problems.</li><li>Use<code>perror()</code> vs<code>strerror()</code> and compare their outputs.</li><li>Add a<code>die()</code> helper to your previous exercises.</li><li>Write a safe wrapper that retries system calls when<code>errno == EAGAIN</code>.</li></ol><p>Next, you’ll put all of this together in Practice 70: Building a Mini Shell in C, where you’ll handle processes, pipes, and signals to create your own working Unix shell prototype.</p>`,63)])])}const g=n(p,[["render",i]]);export{h as __pageData,g as default};
